(()=>{const type=new URLSearchParams(location.search).get('type');if(!type)return;fetch('/collection.json').then(r=>r.json()).then(data=>{const allowed=new Set(data.objects.filter(o=>Array.isArray(o.types)&&o.types.includes(type)).map(o=>'collection-'+o.slug));const cards=[...document.querySelectorAll('[id^="collection-"]')].filter(el=>el.matches('a,article'));cards.forEach(card=>{card.hidden=!allowed.has(card.id)});const shown=cards.filter(card=>!card.hidden);const first=shown[0];if(first)first.scrollIntoView({block:'start'});const note=document.createElement('p');note.className='collection-filter-note';note.textContent=type+' / '+shown.length+' OBJECTS';document.body.prepend(note)}).catch(()=>{})})();
